-- Execute once in the existing shared Supabase project. Does not alter gacha points/tokens.
create table if not exists public.market_wallets(account_id uuid primary key references public.event_users(id) on delete cascade,coins bigint not null default 0 check(coins>=0),updated_at timestamptz not null default now());
create table if not exists public.market_topups(id uuid primary key default gen_random_uuid(),account_id uuid not null references public.event_users(id),amount bigint not null check(amount>0),status text not null default 'pending' check(status in('pending','approved','rejected')),created_at timestamptz not null default now(),reviewed_at timestamptz);
create table if not exists public.market_items(id uuid primary key default gen_random_uuid(),name text not null,description text not null default '',price bigint not null check(price>0),image_path text not null,active boolean not null default true,sort_order int not null default 0,created_at timestamptz not null default now());
create table if not exists public.market_cart_items(account_id uuid not null references public.event_users(id) on delete cascade,item_id uuid not null references public.market_items(id) on delete cascade,quantity int not null default 1 check(quantity between 1 and 99),updated_at timestamptz not null default now(),primary key(account_id,item_id));
create index if not exists market_cart_items_item_idx on public.market_cart_items(item_id);
create table if not exists public.market_orders(id uuid primary key default gen_random_uuid(),buyer_account_id uuid not null references public.event_users(id),recipient_account_id uuid references public.event_users(id),sender_account_id uuid references public.event_users(id),item_id uuid not null references public.market_items(id),item_name text not null,quantity int not null check(quantity>0),unit_price bigint not null,kind text not null check(kind in('purchase','gift')),is_anonymous boolean not null default false,message text not null default '',created_at timestamptz not null default now());
create index if not exists market_orders_buyer_idx on public.market_orders(buyer_account_id,created_at desc);
create index if not exists market_orders_recipient_idx on public.market_orders(recipient_account_id,created_at desc);
alter table public.market_wallets enable row level security;alter table public.market_topups enable row level security;alter table public.market_items enable row level security;alter table public.market_orders enable row level security;alter table public.market_cart_items enable row level security;
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('market-items','market-items',true,5242880,array['image/png']) on conflict(id) do update set public=true,file_size_limit=5242880,allowed_mime_types=array['image/png'];
create or replace function public.market_checkout(p_account_id uuid,p_lines jsonb,p_kind text,p_recipient_nickname text default null,p_anonymous boolean default false,p_message text default '') returns jsonb language plpgsql security definer set search_path=public as $$
declare bal bigint;total bigint:=0;recipient uuid;ln jsonb;it market_items%rowtype;q int;cnt int:=0;
begin
 if p_kind not in('purchase','gift') or jsonb_typeof(p_lines)<>'array' or jsonb_array_length(p_lines)=0 or jsonb_array_length(p_lines)>30 then raise exception '장바구니를 확인해 주세요.';end if;
 if p_kind='gift' then select id into recipient from event_users where nickname_normalized=lower(trim(coalesce(p_recipient_nickname,'')));if recipient is null then raise exception '받는 분 아이디를 찾을 수 없습니다.';end if;if recipient=p_account_id then raise exception '자기 자신에게는 선물할 수 없습니다.';end if;end if;
 insert into market_wallets(account_id) values(p_account_id) on conflict do nothing;select coins into bal from market_wallets where account_id=p_account_id for update;
 for ln in select * from jsonb_array_elements(p_lines) loop q:=(ln->>'quantity')::int;if q<1 or q>99 then raise exception '수량을 확인해 주세요.';end if;select * into it from market_items where id=(ln->>'item_id')::uuid and active=true;if not found then raise exception '판매 중인 상품이 아닙니다.';end if;total:=total+it.price*q;cnt:=cnt+1;if cnt>30 then raise exception '상품 종류가 너무 많습니다.';end if;end loop;
 if bal<total then raise exception '코인이 부족합니다. 현재 잔액: % C',bal;end if;update market_wallets set coins=coins-total,updated_at=now() where account_id=p_account_id;
 for ln in select * from jsonb_array_elements(p_lines) loop q:=(ln->>'quantity')::int;select * into it from market_items where id=(ln->>'item_id')::uuid and active=true;insert into market_orders(buyer_account_id,recipient_account_id,sender_account_id,item_id,item_name,quantity,unit_price,kind,is_anonymous,message) values(p_account_id,case when p_kind='gift' then recipient end,case when p_kind='gift' then p_account_id end,it.id,it.name,q,it.price,p_kind,p_anonymous,left(coalesce(p_message,''),180));end loop;
 return jsonb_build_object('charged',total,'remaining',bal-total);
end $$;
create or replace function public.market_review_topup(p_request_id uuid,p_status text) returns jsonb language plpgsql security definer set search_path=public as $$
declare r market_topups%rowtype;begin if p_status not in('approved','rejected') then raise exception '잘못된 상태입니다.';end if;select * into r from market_topups where id=p_request_id for update;if not found then raise exception '신청을 찾을 수 없습니다.';end if;if r.status<>'pending' then raise exception '이미 처리된 신청입니다.';end if;update market_topups set status=p_status,reviewed_at=now() where id=p_request_id;if p_status='approved' then insert into market_wallets(account_id,coins) values(r.account_id,r.amount) on conflict(account_id) do update set coins=market_wallets.coins+excluded.coins,updated_at=now();end if;return jsonb_build_object('status',p_status,'amount',r.amount);end $$;
grant execute on function public.market_checkout(uuid,jsonb,text,text,boolean,text) to service_role;grant execute on function public.market_review_topup(uuid,text) to service_role;